"use client";

import React, { useState } from "react";
import { AlertCircle, Clock } from "lucide-react";

export function CRMRenewalRiskIndicator() {
  const [days, setDays] = useState(14);

  return (
    <div className="w-full max-w-sm bg-card/45 backdrop-blur-xl border border-border/50 p-5 rounded-2xl shadow-xl select-none font-sans text-foreground">
      <div className="flex items-center justify-between mb-4">
        <div className="flex items-center gap-1.5">
          <AlertCircle className="w-4 h-4 text-amber-400" />
          <span className="text-xs font-bold uppercase tracking-wider text-muted-foreground">Renewal Evaluation</span>
        </div>
        <span className="text-[9px] uppercase font-bold text-amber-400 bg-amber-500/10 px-2 py-0.5 rounded border border-amber-500/20">Churn Risk Level</span>
      </div>

      <div className="space-y-3.5">
        <div className="p-3 rounded-xl bg-amber-500/5 border border-amber-500/10 text-xs flex justify-between items-center">
          <div>
            <p className="font-bold">Contract Expiration</p>
            <p className="text-[10px] text-muted-foreground/60">Review account usage patterns.</p>
          </div>
          <span className="font-black text-amber-400 flex items-center gap-0.5"><Clock className="w-3.5 h-3.5" /> {days} days</span>
        </div>
      </div>
    </div>
  );
}
